import sys


class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        res = 0
        while i > 0:
            res += self.bit[i]
            i -= i & -i
        return res


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:1 + n]
    b = data[1 + n:1 + 2 * n]
    c = data[1 + 2 * n:1 + 3 * n]

    initial_weight = 0
    down = []
    up = []
    same_one = []
    values = []

    for ai, bi, ci in zip(a, b, c):
        if ai == 1:
            initial_weight += ci

        if ai != bi:
            if ai == 1:
                down.append(ci)
            else:
                up.append(ci)
            values.append(ci)
        elif ai == 1:
            same_one.append(ci)
            values.append(ci)

    cur_weight = initial_weight
    cur_cost = 0

    for x in sorted(down, reverse=True):
        cur_weight -= x
        cur_cost += cur_weight

    for x in sorted(up):
        cur_weight += x
        cur_cost += cur_weight

    ans = cur_cost

    if same_one:
        coords = sorted(set(values))
        comp = {x: i + 1 for i, x in enumerate(coords)}

        off_cnt = Fenwick(len(coords))
        off_sum = Fenwick(len(coords))
        on_cnt = Fenwick(len(coords))
        on_sum = Fenwick(len(coords))

        m = len(down)
        sum_off = sum(down)

        for x in down:
            i = comp[x]
            off_cnt.add(i, 1)
            off_sum.add(i, x)

        for x in up:
            i = comp[x]
            on_cnt.add(i, 1)
            on_sum.add(i, x)

        for x in sorted(same_one, reverse=True):
            i = comp[x]

            count_gt = m - off_cnt.sum(i)
            sum_gt = sum_off - off_sum.sum(i)
            count_le = m - count_gt
            delta_off = initial_weight - sum_gt - x * (count_le + 1)

            mid_weight = initial_weight - sum_off
            count_lt = on_cnt.sum(i - 1)
            sum_lt = on_sum.sum(i - 1)
            delta_on = mid_weight + sum_lt - x * count_lt

            cur_cost += delta_off + delta_on
            ans = min(ans, cur_cost)

            off_cnt.add(i, 1)
            off_sum.add(i, x)
            on_cnt.add(i, 1)
            on_sum.add(i, x)
            m += 1
            sum_off += x

    print(ans)


if __name__ == "__main__":
    solve()
